!function(r){function e(e){for(var a,t,d=e[0],n=e[1],o=e[2],y=0,g=[];y<d.length;y++)t=d[y],Object.prototype.hasOwnProperty.call(p,t)&&p[t]&&g.push(p[t][0]),p[t]=0;for(a in n)Object.prototype.hasOwnProperty.call(n,a)&&(r[a]=n[a]);for(s&&s(e);g.length;)g.shift()();return i.push.apply(i,o||[]),m()}function m(){for(var r,e=0;e<i.length;e++){for(var m,t=i[e],d=!0,n=1;n<t.length;n++)m=t[n],0!==p[m]&&(d=!1);d&&(i.splice(e--,1),r=a(a.s=t[0]))}return r}function a(e){if(t[e])return t[e].exports;var m=t[e]={i:e,l:!1,exports:{}};return r[e].call(m.exports,m,m.exports,a),m.l=!0,m.exports}var t={},p={78:0},i=[];a.m=r,a.c=t,a.d=function(r,e,m){a.o(r,e)||Object.defineProperty(r,e,{enumerable:!0,get:m})},a.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},a.t=function(r,e){if(1&e&&(r=a(r)),8&e)return r;if(4&e&&"object"==typeof r&&r&&r.__esModule)return r;var m=Object.create(null);if(a.r(m),Object.defineProperty(m,"default",{enumerable:!0,value:r}),2&e&&"string"!=typeof r)for(var t in r)a.d(m,t,function(e){return r[e]}.bind(null,t));return m},a.n=function(r){var e=r&&r.__esModule?function(){return r.default}:function(){return r};return a.d(e,"a",e),e},a.o=function(r,e){return Object.prototype.hasOwnProperty.call(r,e)},a.p="";var d=window.webpackJsonp=window.webpackJsonp||[],n=d.push.bind(d);d.push=e,d=d.slice();for(var o=0;o<d.length;o++)e(d[o]);var s=n;i.push([38,0]),m()}({38:function(r,e,m){"use strict";m.r(e);var a=m(0);Object(a.a)("de","army",m(39),m(1))},39:function(r){r.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"“黄鼠狼”反坦克炮车","description":"<p>1942年，德军开始急需大量的反坦克装备，于是将75mm火炮和在战场上缴获苏军的76.2mm火炮安装在了Ⅱ号坦克的底盘上，改装为“黄鼠狼”Ⅱ型（又名“貂鼠”，德文“Marder”）反坦克炮车；同时，德军也在捷克产的38吨坦克底盘上安装上76.2mm火炮，称为“黄鼠狼”Ⅲ型反坦克炮车，以此来对付苏军的T-34和KV重型坦克。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_tankdestroyermarder_11.jpg","description":"<h6>75mm“黄鼠狼”Ⅱ型反坦克炮车<br>型号：75mm Pak40/2 Fgst Pzkpfw Ⅱ Sd Kfz 131</h6><p>参数：长：6.36m，宽：2.28m，高：2.20m；车重：10.8t；乘员：5人；</p><p>最大车速：40km，最大行程：190km；</p><p>炮塔左右旋转范围：左32°，右25°，上下活动范围：-8°～+10°；</p><p>装甲厚度：前部：30～35mm，两侧：10～15mm，后部：10～15mm。</p><p>武器配备：1门Pak 40/2型75mm火炮；1挺MG34型7.92mm机枪。</p><p>携弹量：炮弹37发，机枪弹600发。</p><p>1942年6月-1943年6月用Ⅱ号F型坦克底盘改装了576辆，1943年7月-1944年3月又改装了75辆。共生产了650多辆。这些炮车大多都装备东线作战的德军部队。</p>","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_12.jpg","description":"<h6>76.2mm“黄鼠狼”Ⅱ型反坦克炮车<br>型号：76.2mm Pak36（r） Fgst Pzkpfw Ⅱ Sd Kfz 132</h6><p>参数：长：5.65m，宽：2.30m，高：2.60m；车重：11.5t；乘员：4人；</p><p>最大车速：40km，最大行程：190km；</p><p>火炮右旋转50°角；</p><p>装甲厚度：前部：30mm，两侧和后部：14.5mm；</p><p>武器配备：1门苏制76.2mm Pak 36（r）L/51火炮，1挺MG34型7.92mm机枪；</p><p>携弹量：炮弹30发，机枪弹900发。</p><p>该型车是将缴获的苏制76.2mm Pak 36（r）L/51火炮安装在Ⅱ号D/E坦克的底盘上，从而改装为反坦克炮车。该型车从1942年5月完成第一批150辆改装，从1942年4月到1943年6月共完成201台的改装。该型反坦克炮车主要配备在东线作战的德军装甲师和机械化步兵师，在1944年后逐渐从战斗一线消失。</p>","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_13.jpg","description":"<h6>76.2mm“黄鼠狼”Ⅲ型反坦克炮车（MarderⅢ/Sd.kfz.139）<br>型号：Panzerjager 38（t） fur 76.2mm Pak36（r）</h6><p>参数：长：5.85m，宽：2.16m，高：2.50m；车重：10.67t；乘员：4人；</p><p>最大车速：42km，最大行程：185km；</p><p>装甲厚度：10-50mm；</p><p>武器配备：1门苏制76.2mm Pak 36（r）L/51火炮，1挺MG34型7.92mm机枪；</p><p>携弹量：炮弹30发，机枪弹1200发。</p><p>该车用Panzerjager 38吨坦克底盘改装。1942年4月到11月共改装了344辆，1943年改装了19辆。</p>","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_14.jpg","description":"<h6>75mm“黄鼠狼”ⅢH型反坦克炮车（MarderⅢ/Sd.kfz.138 H）<br>型号：75mm Pak43/3 auf Pzkpfw 38（t） Ausf H</h6><p>参数：长：5.77m，宽：2.16m，高：2.51m；车重：10.8t；乘员：4人；</p><p>最大车速：35km，最大行程：240km；</p><p>装甲厚度：8-50mm；</p><p>武器配备：1门75mm Pak 40/3 L/46火炮，1挺MG34型7.92mm机枪；</p><p>携弹量：炮弹38发，机枪弹1200发。</p><p>该车用Pzkpfw 38（t）H型坦克底盘改装。1942年10月至1943年4月共改装242辆，后又改造了175辆。</p>","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_15.jpg","description":"<h6>75mm“黄鼠狼”ⅢM型反坦克炮车（MarderⅢ/Sd.kfz.138 M）<br>型号：Panzerjager 38（t） mit 75mm Pak40/3 Ausf M</h6><p>参数：长：4.95m，宽：2.15m，高：2.48m；车重：10.5t；乘员：4人；</p><p>最大车速：42km，最大行程：185km；</p><p>装甲厚度：8-20mm；</p><p>武器配备：1门75mm Pak 40/3 L/46火炮，1挺MG34型7.92mm机枪。</p><p>携弹量：炮弹27发，机枪弹1200发。</p><p>该炮车将斗室移至车体后部，发动机舱移至车体中部，是这型反坦克炮车外形的一大特点。</p><p>该车用Pzkpfw 38（t） M型坦克底盘改装。1943年4月至1944年5月共改装了975辆。</p>","caption":""}],"part2title":"战场上的“黄鼠狼”反坦克炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyermarder_21.jpg","description":"1945年1月，匈牙利布达佩斯，德军第13装甲师的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车（Ⅱ号F型坦克底盘）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_22.jpg","description":"1943年春天，东线苏联战场，德军（不明单位）的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车，该车已涂上白色冬季涂装。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_23.jpg","description":"1944年8月，法国战场上德军的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_24.jpg","description":"1942年11月，东线苏联斯太林格勒战场，德军（不明单位）的一辆76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_25.jpg","description":"1942年夏季，东线苏联战场上德军（不明单位）的一辆76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_26.jpg","description":"1944年夏季，东线波兰战场，德国武装党卫军第5维京师第5反坦克营的一辆76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_27.jpg","description":"1944年3月，德国武装党卫军第2师的一辆75mm“黄鼠狼”ⅢH（138）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_28.jpg","description":"1943年3月，东线苏联哈尔科夫战场，德国武装党卫军“阿道夫·希特勒警卫旗队”装甲掷弹兵师反坦克“骷髅”营的一辆75mm“黄鼠狼”ⅢH（138）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_29.jpg","description":"1944年7月，西线战场，德国武装党卫军第2“帝国”装甲师第2反坦克营的一辆75mm“黄鼠狼”ⅢM（138）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_30.jpg","description":"1943年冬季，东线苏联战场，德军的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车正在战斗中开进，炮车组士兵正紧张地注视着，作好随时开火的准备。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_31.jpg","description":"1943年东线苏联战场，在1门75mm地面火炮掩护下，德军的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车正准备出发向敌方阵地发动进攻。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_32.jpg","description":"1943年东线苏联战场，德军第560反坦克营的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车隐藏在树林中，炮车乘员正在正在对火炮进行清洗，作下次战斗的准备。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_33.jpg","description":"1943年冬季，东线苏联战场，正在向前线开进的德军第371反坦克营一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车作途中休息。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_34.jpg","description":"1943年东线苏联战场，一队正在泥泞路上行进的德军75mm“黄鼠狼”Ⅱ（131）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_35.jpg","description":"1943年夏天，东线苏联战场，隶属德军第4装甲师第49反坦克营的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车。炮车旁边是在战斗间隙中休息的德军步兵。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_36.jpg","description":"1943年春天，东线苏联战场，德军第10装甲师反坦克营一辆被击毁的75mm“黄鼠狼”Ⅱ（131）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_37.jpg","description":"1944年5月25日，意大利阿基诺地区，德军第1伞兵师反坦克部队的一辆75mm“黄鼠狼”Ⅱ（131）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_38.jpg","description":"1942年东线苏联斯太林格勒战场，德军大德意志师的一辆76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车的乘员正在战车上观察战情。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_39.jpg","description":"1942年东线苏联高加索山区，德国武装党卫军“维京”师的一队76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车正在山区路上行驶。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_40.jpg","description":"1942年冬天，东线苏联斯太林格勒郊外，德军第16步兵师第228反坦克营的一辆76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车，炮车乘员正站在战车上，随车的生活用品放在车体后部。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_41.jpg","description":"1942年东线苏联战场，正在战斗中的一辆德军76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车，炮手正在填弹。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_42.jpg","description":"1942年冬天，东线苏联战场，德军的一队76.2mm“黄鼠狼”Ⅱ（132）型反坦克炮车正停靠在一村庄旁。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_43.jpg","description":"1943年7月，东线苏联战场，一队“黄鼠狼”Ⅲ型反坦克炮车赶来支援德军装甲掷弹兵即将投入的战斗。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_44.jpg","description":"1943年东线苏联战场，德军一辆76.2mm“黄鼠狼”Ⅲ（139）型反坦克炮车正驶过一小镇。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_45.jpg","description":"1943年东线苏联战场，德军一队76.2mm“黄鼠狼”Ⅲ（139）型反坦克炮车正通过一个刚经历战斗的废墟。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_46.jpg","description":"一辆行驶中的德军75mm“黄鼠狼”ⅢH（138）型反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyermarder_47.jpg","description":"1943年东线苏联战场，德军一辆75mm“黄鼠狼”ⅢM（138）型反坦克炮车乘员正在检修车辆。注意该型车的战斗室已移到车体后部。","caption":""}]}')}});